import sys
from math import atan2, pi

def min_angle_pair(vectors):
    def get_quadrant(x, y):
        if x >= 0 and y >= 0:
            return 0
        elif x < 0 and y >= 0:
            return 1
        elif x < 0 and y < 0:
            return 2
        else:
            return 3

    def normalize_angle(angle):
        while angle < 0:
            angle += 2 * pi
        while angle >= 2 * pi:
            angle -= 2 * pi
        return angle

    quadrant_vectors = {}
    for i, (x, y) in enumerate(vectors):
        quadrant = get_quadrant(x, y)
        if quadrant not in quadrant_vectors:
            quadrant_vectors[quadrant] = []
        quadrant_vectors[quadrant].append((i + 1, atan2(y, x)))

    min_angle = float('inf')
    min_pair = (-1, -1)

    for quadrant, vecs in quadrant_vectors.items():
        vecs.sort(key=lambda v: v[1])
        n = len(vecs)
        for i in range(n):
            j = (i + 1) % n
            angle = abs(vecs[j][1] - vecs[i][1])
            if angle > pi:
                angle = 2 * pi - angle
            if angle < min_angle:
                min_angle = angle
                min_pair = (vecs[i][0], vecs[j][0])

    return min_pair

